let benchResultsMode='vessel';
function benchCurrentResult(){
 if(benchResultsMode==='setup'){const saved=studyState.lastBenchRun;if(!saved||saved.kind!=='bench')return null;return {title:'Last Reaction setup result',items:saved.items||[],outcome:saved.outcome||{product:saved.product,equation:saved.equation,note:saved.note,precipitate:saved.precipitate,status:'saved'},mixed:true};}
 const a=selectedEquipment();if(!a||!a.contents?.length)return null;
 return {title:benchVesselLabel(a),items:a.contents,outcome:a.mixed?{...predictMixture(a.contents,a),...analyzeVessel(a)}:null,mixed:!!a.mixed,vessel:a};
}
function benchResultInferences(out){
 if(out.status==='unsupported')return ['The current reaction model cannot assign reliable final products for this combination. This does not establish that no reaction occurs.'];
 const notes=[];if(out.foodInference)notes.push(out.foodInference);
 if(out.precipitate){notes.push('A solid phase is predicted: '+out.product+'. The displayed precipitate is distinct from dissolved species in the surrounding solution.');const ions={'Silver chloride precipitate':'silver(I) and chloride ions','Silver iodide precipitate':'silver(I) and iodide ions','Lead(II) iodide precipitate':'lead(II) and iodide ions','Lead(II) chloride precipitate':'lead(II) and chloride ions','Lead(II) sulfate precipitate':'lead(II) and sulfate ions','Copper(II) hydroxide precipitate':'copper(II) and hydroxide ions','Iron(II) hydroxide precipitate':'iron(II) and hydroxide ions','Iron(III) hydroxide precipitate':'iron(III) and hydroxide ions','Magnesium hydroxide precipitate':'magnesium and hydroxide ions','Calcium hydroxide precipitate':'calcium and hydroxide ions','Calcium carbonate precipitate':'calcium and carbonate ions','Calcium sulfate precipitate':'calcium and sulfate ions'}[out.product];if(ions)notes.push('For the entered reagents, this is consistent with '+ions+' forming a sparingly soluble solid under the modeled conditions. Colour alone is not a unique identification.');}
 const tests={hydrogen:'A burning splint gives a characteristic pop in the virtual hydrogen test.',oxygen:'A glowing splint relights in oxygen.',carbonDioxide:'Carbon dioxide turns limewater cloudy; extinguishing a flame alone does not uniquely identify CO₂.',ammonia:'Ammonia turns damp red litmus blue; a splint test is not characteristic.',sulfurDioxide:'Sulfur dioxide is colourless and may remain partly dissolved. Its identity here comes from the modeled reactants, not from gas colour.'};
 if(out.gas)notes.push('Gas predicted: '+gasName(out.gas)+'. '+(tests[out.gas]||'A separate confirmatory test is needed.'));
 if(Number.isFinite(out.pH))notes.push(`Modeled pH ${out.pH.toFixed(2)} indicates ${out.pH<6.95?'an acidic':out.pH>7.05?'an alkaline':'an approximately neutral'} solution at 25 °C. Indicator colour depends on this pH; unindicated acids and alkalis can both be colourless.`);
 if(out.equation?.includes('⇌'))notes.push('The equilibrium arrow indicates that species proportions depend on concentration and conditions; formation of a complex can change colour without producing a solid.');
 if(/MnO₄|Fe³⁺.*Fe²⁺|Cu²⁺.*CuI|S₂O₃²⁻.*S₄O₆/.test(out.equation||''))notes.push('The equation describes electron transfer. The limiting reagent controls conversion, and excess coloured reagent can remain visible.');
 if(!notes.length)notes.push('A visible colour change is not required for a chemical reaction. Interpret the equation and the observation together; absence of visible change alone does not prove no reaction.');
 if(out.status==='conditional'||out.status==='qualitative')notes.push('This result is '+out.status+': read the observation for the assumed conditions and limits.');
 notes.push('These are simulation-based inferences, not independent confirmation of the identity of an experimental sample.');return notes;
}
function benchReactionResultsHtml(){const result=benchCurrentResult(),chosen=benchResultsMode==='setup'?'setup':selectedApp||'',vessels=apparatus.filter(a=>acceptsLiquid(a.type)||acceptsSolid(a.type)||a.type==='separatoryFunnel');return `<label class="bench-results-label" for="benchResultVessel">View reaction in<select id="benchResultVessel"><option value="">Choose a vessel</option>${vessels.map(a=>`<option value="${a.id}" ${chosen===a.id?'selected':''}>${esc(benchVesselLabel(a))} · ${(a.volume||0).toFixed(1)} mL</option>`).join('')}<option value="setup" ${chosen==='setup'?'selected':''}>Last Reaction setup result</option></select></label>${!result?'<p class="notice">Select a vessel containing reagents, or choose the last completed Reaction setup result.</p>':`<h3>${esc(result.title)}</h3>${!result.mixed?`<p class="notice">These reagents are staged. No mixed-reaction result has been recorded for this vessel yet.</p>${result.items.length>1?'<button type="button" class="btn soft small" id="benchResultMix">Mix selected vessel</button>':''}`:`<div class="bench-result-status">${esc(result.outcome.status||'modeled')} prediction</div><div class="bench-results-grid"><section><h3>Observation & products</h3><p><b>${esc(result.outcome.product||'No product assigned')}</b></p><p>${esc(result.outcome.note||'No observation available.')}</p></section><section><h3>Equation / equilibrium</h3><p class="bench-result-equation">${esc(result.outcome.equation||'No equation assigned.')}</p><small>Net ionic equations omit spectator ions. Conditional or unsupported predictions are identified explicitly.</small></section><section class="bench-result-inferences"><h3>Inferences</h3><ul>${benchResultInferences(result.outcome).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section></div>`}${result.items.length?`<details class="bench-result-inputs"><summary>Reagents and measured amounts used</summary><div class="bench-result-table"><table class="table"><thead><tr><th>Reagent</th><th>Added stock / mol L⁻¹</th><th>Amount</th></tr></thead><tbody>${result.items.map(c=>{const match=String(c.formula||'').match(/(\d+(?:\.\d+)?)\s*M\b/i),C=c.molarity!=null&&c.molarity!==''?Number(c.molarity):match?Number(match[1]):null;return `<tr><td>${esc(c.reagent)}</td><td>${Number.isFinite(C)?C:'—'}</td><td>${c.mass>0?Number(c.mass).toFixed(3)+' g':Number(c.volume||0).toFixed(2)+' mL'}</td></tr>`;}).join('')}</tbody></table></div></details>`:''}`}<p class="bench-results-note">Results use the current combined amounts and modeled conditions. Reagent quantities are the added inventory; the model does not track every intermediate or gas already lost during earlier steps. <a href="bench-chemistry-reference.txt" target="_blank" rel="noopener">Chemistry coverage & references</a></p>`;}
function benchRefreshResults(){const el=document.getElementById('benchReactionResults');if(!el)return;el.innerHTML=benchReactionResultsHtml();const select=document.getElementById('benchResultVessel');select.onchange=()=>{if(select.value==='setup'){benchResultsMode='setup';benchRefreshResults();}else{benchResultsMode='vessel';selectedApp=select.value||null;redrawBench();}persistWorkspace();};const mixButton=document.getElementById('benchResultMix');if(mixButton)mixButton.onclick=()=>{const a=selectedEquipment();if(!a||a.contents.length<2)return;a.mixed=true;a.extractionDone=false;a.phaseTint=null;const reaction=analyzeVessel(a);if(reaction.gas){a.generatedGas=reaction.gas;a.gasTrapped=false;}redrawBench();persistWorkspace();};}
